(function(root){
 'use strict';
 const C=UserDataCore,S=SyncCore,D=DriveClient,E=id=>document.getElementById(id),CONFIG='drivePreferences';
 let config={},account='',working=false,sdkReady=false,pending=false,recovery=false,timer,initializing=true,needsReload=false;
 let lastError='';
 const policy=AutoSyncPolicy.create({run:reason=>sync(reason==='manual',reason),enabled:()=>!!config.auto&&!!account&&D.ready()&&E('driveConsent').checked&&navigator.onLine&&!recovery&&!needsReload,changed:()=>statusUI()});
 function statusUI(){const node=E('driveSidebarStatus');if(!node)return;let text=initializing?'동기화 준비 중':!account?'Google 연결 필요':!D.ready()?'Google 재연결 필요':!E('driveConsent').checked?'동기화 전송 동의 필요':recovery?'동기화 복구 필요':!navigator.onLine?'오프라인 · 변경 보관 중':working?'동기화 중…':lastError?'동기화 오류 · 설정 확인':pending?'받은 변경 · 적용 대기':!config.auto?'자동 동기화 OFF':policy.dirty()?'동기화 대기':config.lastSync?'동기화 완료 · '+new Date(config.lastSync).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'동기화 대기';node.textContent='☁ '+text;node.title=lastError||text;node.dataset.error=String(!!lastError)}
 const stateKey=()=> 'driveState:'+account;
 const withLock=fn=>navigator.locks?navigator.locks.request('aka-drive-sync-v1',fn):Promise.reject(Error('이 브라우저는 안전한 동기화 잠금을 지원하지 않습니다.'));
 function message(text,error=false){E('driveStatus').textContent=text;E('driveStatus').dataset.error=String(error);lastError=error?text:'';statusUI()}
 function ui(){const auth=D.ready(),disabled=working||initializing;E('drivePrepare').hidden=sdkReady;E('drivePrepare').disabled=disabled||!navigator.onLine;E('driveConnect').hidden=!sdkReady;E('driveConnect').disabled=disabled||!navigator.onLine;E('driveDisconnect').disabled=disabled||!account;E('driveSync').disabled=disabled||!auth||!E('driveConsent').checked||recovery||needsReload;E('driveApply').hidden=!pending;E('driveApply').disabled=disabled||recovery||needsReload;E('driveAuto').checked=!!config.auto;E('driveAuto').disabled=disabled;E('driveClientId').disabled=disabled||!!account;E('driveConsent').disabled=disabled||!account;E('driveRecovery').hidden=!recovery;E('driveReload').hidden=!needsReload;E('driveAccount').textContent=account?'연결 계정 · …'+account.slice(-6)+(auth?'':' · 다시 연결 필요'):'연결되지 않음';E('driveLastSync').textContent=config.lastSync?new Date(config.lastSync).toLocaleString():'아직 동기화하지 않음';statusUI()}
 function editing(){return (typeof busy!=='undefined'&&busy)||root.Notes?.isActive()||root.ReaderSelection?.isActive?.()||root.BetaTranslation?.isRunning()||root.Highlights?.isActive()||[...document.querySelectorAll('dialog[open]')].some(d=>d.id!=='settingsDialog')}
 async function prepare(){working=true;ui();message('Google 로그인 파일 준비 중…');try{await D.prepare();sdkReady=true;message('Google 연결을 눌러 계정을 선택하세요.')}catch(e){message(e.message,true)}finally{working=false;ui()}}
 function connect(){const id=E('driveClientId').value.trim();working=true;E('driveConsent').checked=false;ui();message('Google 계정 연결 중…');D.connect(id).then(async sub=>{account=sub;pending=false;config=await C.metaGet(CONFIG)||{};config.clientId=id;await C.metaPut(CONFIG,config);const state=await C.metaGet(stateKey());pending=!!state&&!sameView(await S.project(state.ops),state.baseline);message('연결됐습니다. 전송 동의 후 자동 동기화를 켜면 바로 시작합니다.')}).catch(e=>{account='';message(e.message,true)}).finally(()=>{working=false;ui()})}
 function disconnect(){if(working)return;D.clear();account='';pending=false;policy.stop();E('driveConsent').checked=false;message('이 기기의 연결을 해제했습니다. 기기 및 Drive 데이터는 유지됩니다. Google 권한 철회는 Google 계정의 연결 앱 관리에서 할 수 있습니다.');ui()}
 async function captureState(){let state=await C.metaGet(stateKey())||S.state();const current=await C.snapshot();state=S.capture(state,current);await C.metaPut(stateKey(),state);return state}
 async function sync(manual=true,reason='manual'){if(working||!account||!E('driveConsent').checked||recovery||needsReload)return false;if(!D.ready()){message('Google 연결이 만료됐습니다. 다시 연결하세요.',true);ui();return false}if(!manual&&!config.auto)return false;if(!navigator.onLine){message('오프라인입니다. 이 기기의 변경 사항은 유지되며, 연결 후 동기화할 수 있습니다.');return false}working=true;ui();try{await withLock(async()=>{const subject=account;message('Drive의 변경 기록을 확인하고 있습니다…');const files=await D.list();let remote=[],downloaded=0;for(const [i,file]of files.entries()){message('Drive 변경 기록 읽는 중 · '+(i+1)+'/'+files.length);const text=await D.read(file);downloaded+=new TextEncoder().encode(text).length;if(downloaded>50*1024*1024)throw Error('베타 동기화 전체 용량 한도(50MB)에 도달했습니다.');remote=S.join(remote,await S.decode(text))}
   let state=await C.exclusive(captureState);state.ops=S.join(state.ops,remote);const view=await S.project(state.ops);S.payload(view,await C.exclusive(C.snapshot));await C.metaPut(stateKey(),state);
   const ids=new Set(remote.map(o=>o.id)),outgoing=state.ops.filter(o=>!ids.has(o.id));if(outgoing.length){message('이 기기의 변경 기록을 Drive에 저장하고 있습니다…');await D.upload(await S.encode(outgoing))}
   if(subject!==account)throw Error('연결 계정이 변경됐습니다.');config.lastSync=Date.now();await C.metaPut(CONFIG,config);pending=!sameView(view,state.baseline);E('driveChanges').textContent='동시 수정 보존: '+view.conflicts.length+'개 · 기록 '+state.ops.length+'개';message(pending?'동기화가 완료됐습니다. 받은 변경 사항 적용을 누르면 앱을 다시 열어 반영합니다.':'모든 변경 사항이 동기화됐습니다.');
  });return true}catch(e){message('동기화 중지: '+e.message+' 기기 데이터와 기존 Drive 기록은 유지됩니다.',true);return false}finally{working=false;ui()}}
 function sameView(view,baseline){return C.canonical(view.data)===C.canonical(baseline)}
 async function apply(){if(working||!account||recovery||needsReload)return;if(editing()){message('선택·메모 편집 또는 다른 작업을 마친 뒤 적용하세요.',true);return}working=true;const main=document.querySelector('main');if(main)main.inert=true;ui();try{await withLock(()=>C.exclusive(async()=>{let state=await captureState();const view=await S.project(state.ops),current=await C.snapshot(),payload=S.payload(view,current);await SyncApply.apply(payload,async()=>{state.baseline=view.data;state.refs=view.refs;await C.metaPut(stateKey(),state)},stateKey());pending=false;needsReload=true;root.UserData?.changed();message('받은 변경 사항을 적용했습니다. 앱을 다시 엽니다.');location.reload()}))}catch(e){recovery=!!await C.metaGet('driveRecovery');message(e.message,true)}finally{if(main)main.inert=false;working=false;ui()}}
 function schedule(){if(!initializing&&config.auto&&account&&D.ready()&&E('driveConsent').checked)policy.start();else{policy.stop();statusUI()}}
 function pageMoved({from,to,direct=false}){policy.notify('position',{distance:Math.abs(to-from),direct})}
 async function recover(){if(working)return;working=true;ui();try{await withLock(()=>C.exclusive(SyncApply.recover));recovery=false;needsReload=true;message('적용 전 데이터를 복구했습니다. 앱을 다시 열어 주세요.')}catch(e){message('복구 실패: '+e.message,true)}finally{working=false;ui()}}
 async function init(){E('drivePrepare').onclick=prepare;E('driveConnect').onclick=connect;E('driveDisconnect').onclick=disconnect;E('driveSync').onclick=()=>policy.request('manual');E('driveApply').onclick=apply;E('driveConsent').onchange=()=>{schedule();ui()};E('driveRecovery').onclick=recover;E('driveReload').onclick=()=>location.reload();E('driveAuto').onchange=async()=>{config.auto=E('driveAuto').checked;try{await C.metaPut(CONFIG,config);schedule()}catch(e){message(e.message,true)}ui()};window.addEventListener('aka-user-data-changed',e=>{const kind=e.detail?.kind;if(kind==='records')policy.notify('records');else if(kind==='position')policy.notify('position')});for(const event of ['pointerdown','keydown','input','scroll'])document.addEventListener?.(event,()=>policy.activity(),{capture:true,passive:true});document.addEventListener?.('visibilitychange',()=>{if(document.visibilityState==='visible'){policy.activity();policy.request('resume')}else if(policy.dirty())policy.request('background')});window.addEventListener('online',()=>{schedule();ui()});window.addEventListener('offline',()=>{message('오프라인입니다. 기기에 계속 저장하며, 온라인 연결 후 동기화하세요.');ui()});setInterval(()=>{ui();if(document.visibilityState==='visible')policy.request('poll')},300000);setInterval(ui,15000);
  try{config=await C.metaGet(CONFIG)||{};E('driveClientId').value=root.AKA_DRIVE_CONFIG?.clientId||config.clientId||'';recovery=!!await C.metaGet('driveRecovery');message(recovery?'이전 적용이 중단됐습니다. 적용 전 데이터 복구를 먼저 실행하세요.':E('driveClientId').value?'Google 로그인 준비를 눌러 연결하세요.':'Google 연동 준비 전입니다. 개발자 설정에 웹 OAuth 클라이언트 ID를 입력하세요.')}catch(e){message(e.message,true)}initializing=false;ui()
 }
 root.DriveSync={sync,apply,disconnect,pageMoved};init();
})(globalThis);
